function validate([x, y, bound]) {
  if (![x, y, bound].every(Number.isInteger)) return 'x, y and bound must be integers.';
  if (x < 1 || x > 100 || y < 1 || y > 100) return 'x and y are between 1 and 100.';
  if (bound < 0 || bound > 1000000) return 'bound is between 0 and 1000000.';
  return null;
}

