function powerfulIntegers(x, y, bound) {
  // Test every candidate value: is it some power of x plus some power of y?
  const isPowerOf = (value, base) => {
    if (value < 1) return false;
    if (base === 1) return value === 1;
    while (value % base === 0) value /= base;
    return value === 1;
  };
  const powersOfX = [1];
  if (x > 1) while (powersOfX[powersOfX.length - 1] * x <= bound) powersOfX.push(powersOfX[powersOfX.length - 1] * x);
  const result = [];
  for (let value = 2; value <= bound; value++) {
    if (powersOfX.some(p => isPowerOf(value - p, y))) result.push(value);
  }
  return result;
}

