function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const pickBase = (top) => {
    const r = rand();
    if (r < 0.15) return 1;
    if (r < 0.4) return int(2, 3);
    return int(1, top);
  };
  if (size === 'large') {
    const bound = rand() < 0.7 ? int(900000, 1000000) : int(0, 1000000);
    return [pickBase(100), pickBase(100), bound];
  }
  return [pickBase(12), pickBase(12), int(0, 80)];
}
